"""CARLA-lazy original-frame capture core for a reviewed Native caravan site.

The caller owns world restoration, actor/camera lifetime, and source sealing.
This module never treats an intended merge as observed occupancy or legal safety.
"""
import hashlib
import json
import math
from pathlib import Path
from queue import Empty, Queue

from caravan_control import apply, command
from caravan_entry import plan_entry

CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
SOURCE_KEYS = ("business_district_source", "caravan_membership_source",
               "route_source", "lane_source")


def validate_site(packet, root, native_map_id):
    """Require a reviewed Native site and bind its four original context files."""
    if packet.get("site_review_status") != "reviewed_native_site":
        raise ValueError("Reviewed Native caravan site required")
    for key in ("reviewer", "district_review_basis", "caravan_review_basis",
                "highway_review_basis", "camera_review_basis"):
        value = packet.get(key)
        if (not isinstance(value, str) or not value.strip() or
                any(word in value.lower() for word in ("synthetic", "diagnostic", "fixture"))):
            raise ValueError("Original Native site review required: " + key)
    if packet.get("native_map_id") in (None, "", "FixtureMap", "TownX"):
        raise ValueError("Original Native map identity required")
    if packet.get("native_map_id") != native_map_id:
        raise ValueError("Native map differs from reviewed caravan site")
    if packet.get("outside_business_district") is not True or packet.get("caravan_or_motorcade") is not True:
        raise ValueError("District and caravan activation unresolved")
    if not packet.get("highway_id") or not packet.get("road_id"):
        raise ValueError("Reviewed highway and road IDs required")
    if not isinstance(packet.get("road_forward_xy"), list) or len(packet["road_forward_xy"]) != 2:
        raise ValueError("Reviewed highway direction required")
    if any(type(value) not in (int, float) or not math.isfinite(value)
           for value in packet["road_forward_xy"]):
        raise ValueError("Finite highway direction required")
    if math.hypot(*packet["road_forward_xy"]) <= 0:
        raise ValueError("Nonzero highway direction required")
    if not isinstance(packet.get("roadway_polygon_xy_m"), list) or len(packet["roadway_polygon_xy_m"]) < 4:
        raise ValueError("Reviewed highway polygon required")
    hashes = {}
    root = Path(root).resolve()
    for key in SOURCE_KEYS:
        ref = packet.get(key)
        if not isinstance(ref, dict) or not isinstance(ref.get("path"), str) or not isinstance(ref.get("sha256"), str):
            raise ValueError("Original context source required: " + key)
        relative = Path(ref["path"])
        if relative.is_absolute() or not relative.parts or ".." in relative.parts:
            raise ValueError("Unsafe context source: " + key)
        path = (root / relative).resolve()
        if not path.is_relative_to(root) or not path.is_file():
            raise ValueError("Missing original context source: " + key)
        data = path.read_bytes()
        if not data or len(data) > 2 * 1024 * 1024:
            raise ValueError("Invalid original context source size: " + key)
        data.decode("utf-8")
        digest = hashlib.sha256(data).hexdigest()
        if digest != ref["sha256"]:
            raise ValueError("Changed original context source: " + key)
        hashes[key] = digest
    return hashes


def body(actor):
    vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
    points = [[float(vertex.x), float(vertex.y)] for vertex in vertices]
    if len(points) < 4 or any(not all(math.isfinite(value) for value in point) for point in points):
        raise ValueError("Incomplete original Native vehicle body")
    return points


def state(actor):
    transform = actor.get_transform()
    velocity = actor.get_velocity()
    points = body(actor)
    yaw = float(transform.rotation.yaw)
    speed = math.hypot(float(velocity.x), float(velocity.y))
    if not math.isfinite(yaw) or not math.isfinite(speed):
        raise ValueError("Nonfinite original Native vehicle state")
    blueprint_id = getattr(actor, "type_id", None)
    if not isinstance(blueprint_id, str) or not blueprint_id:
        raise ValueError("Original Native vehicle type identity required")
    return {"actor_id": int(actor.id), "blueprint_id": blueprint_id,
            "body_vertices_xy_m": points,
            "position_xy": [float(transform.location.x), float(transform.location.y)],
            "yaw_deg": yaw, "speed_mps": speed}


def _image(queue, frame):
    for _ in range(6):
        try:
            image = queue.get(timeout=10)
        except Empty as error:
            raise ValueError("Original source camera frame missing") from error
        if image.frame == frame:
            return image
        if image.frame > frame:
            raise ValueError("Source camera skipped Native frame")
    raise ValueError("Original source camera frame join failed")


def capture_frames(world, carla, caravan, entrant, sensors, encoders, mapping,
                   history, pipeline_capture, packet, *, outcome, frames=900):
    """Drive four vehicles and join all four cameras to each original Native tick."""
    if len(caravan) < 3 or len({actor.id for actor in caravan + [entrant]}) != len(caravan) + 1:
        raise ValueError("Three distinct caravan vehicles and distinct entrant required")
    if set(sensors) != set(CAMERAS) or set(encoders) != set(CAMERAS):
        raise ValueError("Four original source cameras and encoders required")
    if type(frames) is not int or frames < 2:
        raise ValueError("Original frame count required")
    if outcome not in ("occupy", "stop_before"):
        raise ValueError("Exact caravan comparison outcome required")
    queues = {name: Queue() for name in CAMERAS}
    for name, sensor in sensors.items():
        sensor.listen(lambda image, camera=name: queues[camera].put(image))
    plan = None
    last_frame = None
    last_time = None
    count = 0
    for index in range(frames):
        members_before = [state(actor) for actor in caravan]
        entrant_before = state(entrant)
        if plan is None:
            plan = plan_entry(packet, members_before, entrant_before["body_vertices_xy_m"],
                              gap_index=packet["selected_gap_index"], outcome=outcome)
        for member in members_before:
            actor = next(actor for actor in caravan if actor.id == member["actor_id"])
            target = [member["position_xy"][0] + packet["road_forward_xy"][0] * 25,
                      member["position_xy"][1] + packet["road_forward_xy"][1] * 25]
            values = command(member["position_xy"], member["yaw_deg"], member["speed_mps"],
                             target, target_speed_mps=packet["target_speed_mps"])
            apply(actor, carla, values)
        waypoints = plan["waypoints_xy_m"]
        target = waypoints[0]
        if outcome == "occupy" and len(waypoints) > 1:
            if math.dist(entrant_before["position_xy"], target) < 1.0:
                target = waypoints[1]
        values = command(entrant_before["position_xy"], entrant_before["yaw_deg"],
                         entrant_before["speed_mps"], target,
                         target_speed_mps=packet["target_speed_mps"])
        apply(entrant, carla, values)
        world.tick()
        snapshot = world.get_snapshot()
        frame = int(snapshot.frame)
        time_s = float(snapshot.timestamp.elapsed_seconds)
        if last_frame is not None and frame != last_frame + 1:
            raise ValueError("Original Native frame cadence broken")
        if not math.isfinite(time_s) or (last_time is not None and abs(time_s - last_time - .05) > 1e-4):
            raise ValueError("Original Native 20 Hz time cadence broken")
        last_frame = frame
        last_time = time_s
        for name in CAMERAS:
            encoders[name].write(bytes(_image(queues[name], frame).raw_data))
        pipeline_capture.capture(frame, time_s)
        mapping.append(frame, time_s)
        members_after = [state(actor) for actor in caravan]
        entrant_after = state(entrant)
        selected = {member["actor_id"]: member for member in members_after}
        rear = selected[plan["rear_actor_id"]]
        front = selected[plan["front_actor_id"]]
        waypoint = world.get_map().get_waypoint(entrant.get_location(), project_to_road=False)
        if waypoint is None or type(waypoint.lane_id) is not int:
            raise ValueError("Original Native entrant lane readback missing")
        history.write(json.dumps({"frame": frame, "time_s": time_s,
                                  "road_id": packet["road_id"],
                                  "caravan_members": [{key: member[key] for key in ("actor_id", "blueprint_id", "body_vertices_xy_m")}
                                                      for member in members_after],
                                  "entering_vehicle": {key: entrant_after[key] for key in
                                                       ("actor_id", "blueprint_id", "body_vertices_xy_m")},
                                  "participants": {
                                      "rear": {"actor_id": rear["actor_id"], "body_vertices_m": rear["body_vertices_xy_m"]},
                                      "subject": {"actor_id": front["actor_id"], "body_vertices_m": front["body_vertices_xy_m"]},
                                      "entrant": {"actor_id": entrant_after["actor_id"],
                                                  "body_vertices_m": entrant_after["body_vertices_xy_m"],
                                                  "lane_id": int(waypoint.lane_id)}}},
                                 separators=(",", ":")) + "\n")
        count = index + 1
    return {"frames": count, "first_frame": last_frame - count + 1,
            "last_frame": last_frame, "plan": plan,
            "physical_acceptance_claimed": False,
            "without_danger_judgment": "unresolved"}

"""Bounded Native vehicle controls for the caravan and entering participant.

The clearance parameter is a control safety setting, not a legal danger cutoff.
"""
import math


def _finite(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("Finite " + name + " required")
    return float(value)


def command(position_xy, yaw_deg, speed_mps, waypoint_xy, *, target_speed_mps,
            nearest_body_clearance_m=None, control_clearance_m=3.0):
    x, y = (_finite(value, "vehicle position") for value in position_xy)
    tx, ty = (_finite(value, "waypoint") for value in waypoint_xy)
    yaw = math.radians(_finite(yaw_deg, "Native heading"))
    speed = _finite(speed_mps, "Native speed")
    target_speed = _finite(target_speed_mps, "target speed")
    if speed < 0 or target_speed < 0 or target_speed > 15:
        raise ValueError("Unsafe speed input")
    clearance = None if nearest_body_clearance_m is None else _finite(nearest_body_clearance_m, "body clearance")
    if control_clearance_m <= 0:
        raise ValueError("Positive control clearance required")
    dx, dy = tx - x, ty - y
    distance = math.hypot(dx, dy)
    angle = math.atan2(dy, dx) if distance > 1e-6 else yaw
    error = math.atan2(math.sin(angle - yaw), math.cos(angle - yaw))
    steer = max(-.6, min(.6, 1.2 * error))
    if clearance is not None and clearance < control_clearance_m:
        return {"throttle": 0.0, "brake": 1.0, "steer": 0.0, "reverse": False,
                "reason": "engineering_body_clearance_guard"}
    if distance <= .75 or (abs(error) > .8 and speed > 2):
        return {"throttle": 0.0, "brake": min(1.0, max(.25, speed / 6)),
                "steer": steer, "reverse": False, "reason": "waypoint_or_heading_brake"}
    speed_error = target_speed - speed
    return {"throttle": max(0.0, min(.45, speed_error * .18)),
            "brake": max(0.0, min(.8, -speed_error * .25)),
            "steer": steer, "reverse": False, "reason": "waypoint_tracking"}


def apply(actor, carla, values):
    required = {"throttle", "brake", "steer", "reverse", "reason"}
    if set(values) != required or values["reverse"] is not False:
        raise ValueError("Incomplete forward Native vehicle control")
    control = carla.VehicleControl(throttle=values["throttle"], brake=values["brake"],
                                   steer=values["steer"], reverse=False)
    actor.apply_control(control)
    return control

"""Spawn distinct motor vehicles for a source-reviewed caravan route."""
from contextlib import contextmanager

def _xy(actor):
 p=actor.get_location();return float(p.x),float(p.y)
@contextmanager
def spawn_caravan(world, vehicles, *, min_initial_separation_m=3.0):
 if len(vehicles)<3:raise ValueError('At least three caravan participants required')
 owned=[]
 try:
  for blueprint,transform in vehicles:
   actor=world.try_spawn_actor(blueprint,transform)
   if actor is None:raise ValueError('Native caravan vehicle spawn failed')
   owned.append(actor)
  positions=[_xy(actor) for actor in owned]
  for i,p in enumerate(positions):
   for q in positions[i+1:]:
    if ((p[0]-q[0])**2+(p[1]-q[1])**2)**.5<min_initial_separation_m:
     raise ValueError('Caravan initial positions overlap')
  yield owned
 finally:
  for actor in reversed(owned):actor.destroy()

"""Four synchronized original RGB viewpoints for the Native caravan."""
from contextlib import contextmanager

PROFILE = {"overview": (1920, 1080), "approach": (1280, 720),
           "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


@contextmanager
def source_cameras(world, entrant, transforms):
    if set(transforms) != set(PROFILE):
        raise ValueError("Four reviewed source camera poses required")
    sensors = {}
    try:
        for name, (width, height) in PROFILE.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            for key, value in (("image_size_x", width), ("image_size_y", height),
                               ("fov", 90), ("sensor_tick", .05)):
                blueprint.set_attribute(key, str(value))
            kwargs = {"attach_to": entrant} if name == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError("Native source camera spawn failed: " + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Original-frame caravan gap and entering-vehicle occupancy observations."""
import hashlib,json,math
from pathlib import Path
from shapely.geometry import MultiPoint,Polygon,Point
REQUIRED=('road_context.json','caravan_history.jsonl','video_frames.jsonl')
def _finite(x,label):
 if isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x):raise ValueError('Missing finite '+label)
 return float(x)
def _rows(path):return [json.loads(s) for s in path.read_text().splitlines() if s.strip()]
def _source(root,ref,key):
 if not isinstance(ref,dict) or not isinstance(ref.get('path'),str) or not isinstance(ref.get('sha256'),str):raise ValueError('Missing original context source: '+key)
 rel=Path(ref['path'])
 if rel.is_absolute() or not rel.parts or '..' in rel.parts or ref['path'] in ('','.'):raise ValueError('Unsafe context source: '+key)
 path=root/rel
 if not path.is_file() or not path.resolve().is_relative_to(root.resolve()):raise ValueError('Missing or escaping context source: '+key)
 if path.stat().st_size==0 or path.stat().st_size>2*1024*1024:raise ValueError('Empty or oversized context source: '+key)
 path.read_text(encoding='utf-8')
 digest=hashlib.sha256(path.read_bytes()).hexdigest()
 if digest!=ref['sha256']:raise ValueError('Changed original context source: '+key)
 return digest
def _body(actor):
 if not isinstance(actor,dict) or not isinstance(actor.get('body_vertices_xy_m'),list) or len(actor['body_vertices_xy_m'])<4:raise ValueError('Missing complete body')
 poly=MultiPoint([(_finite(p[0],'body x'),_finite(p[1],'body y')) for p in actor['body_vertices_xy_m']]).convex_hull
 if poly.area<=0:raise ValueError('Degenerate body')
 return poly
def analyze(root:Path)->dict:
 root=Path(root);hashes={}
 for name in REQUIRED:
  p=root/name
  if not p.is_file():raise ValueError('Missing original source: '+name)
  hashes[name]=hashlib.sha256(p.read_bytes()).hexdigest()
 ctx=json.loads((root/'road_context.json').read_text())
 for key in ('native_map_id','highway_id','road_id'):
  if not ctx.get(key):raise ValueError('Missing sourced caravan context: '+key)
 context_hashes={key:_source(root,ctx.get(key),key) for key in ('business_district_source','caravan_membership_source','route_source','lane_source')}
 if ctx.get('outside_business_district') is not True or ctx.get('caravan_or_motorcade') is not True:raise ValueError('Caravan/district activation unresolved')
 road=Polygon(ctx.get('roadway_polygon_xy_m',[]))
 if not road.is_valid or road.area<=0:raise ValueError('Invalid roadway')
 forward=ctx.get('road_forward_xy')
 if not isinstance(forward,list) or len(forward)!=2:raise ValueError('Road direction missing')
 fx,fy=(_finite(v,'road direction') for v in forward);norm=math.hypot(fx,fy)
 if norm==0:raise ValueError('Zero road direction')
 fx,fy=fx/norm,fy/norm
 rows,frames=_rows(root/'caravan_history.jsonl'),_rows(root/'video_frames.jsonl')
 if len(rows)<2 or len(rows)!=len(frames):raise ValueError('Incomplete caravan history')
 prev=(-1,-math.inf);samples=[];member_centers={};member_ids=None;entrant_id=None;forward_motion={};member_types=None;entrant_type=None
 for i,(row,frame) in enumerate(zip(rows,frames)):
  fid,t=row.get('frame'),_finite(row.get('time_s'),'time')
  if type(fid) is not int or fid<=prev[0] or t<=prev[1]:raise ValueError('Nonmonotone original history')
  if i and (fid!=prev[0]+1 or abs(t-prev[1]-.05)>1e-4):raise ValueError('Original 20 Hz frame cadence required')
  prev=fid,t
  if frame.get('video_frame')!=i or frame.get('carla_frame')!=fid or frame.get('time_s')!=t:raise ValueError('Original frame join failed')
  if row.get('road_id')!=ctx.get('road_id'):raise ValueError('Wrong caravan road')
  members=row.get('caravan_members')
  if not isinstance(members,list) or len(members)<3 or len({m.get('actor_id') for m in members})!=len(members):raise ValueError('Three distinct caravan vehicles required')
  ids={m.get('actor_id') for m in members}
  if any(type(actor_id) is not int for actor_id in ids):raise ValueError('Original caravan actor IDs required')
  if member_ids is None:member_ids=ids
  elif ids!=member_ids:raise ValueError('Caravan membership changed across original frames')
  types={m['actor_id']:m.get('blueprint_id') for m in members}
  if any(not isinstance(kind,str) or not kind for kind in types.values()):raise ValueError('Original caravan vehicle types required')
  if member_types is None:member_types=types
  elif types!=member_types:raise ValueError('Caravan vehicle types changed across original frames')
  entrant=row.get('entering_vehicle')
  if not isinstance(entrant,dict) or type(entrant.get('actor_id')) is not int or entrant['actor_id'] in {m.get('actor_id') for m in members}:
   raise ValueError('Distinct entering vehicle required')
  if entrant_id is None:entrant_id=entrant['actor_id']
  elif entrant['actor_id']!=entrant_id:raise ValueError('Entering vehicle identity changed across original frames')
  if not isinstance(entrant.get('blueprint_id'),str) or not entrant['blueprint_id']:raise ValueError('Original entering vehicle type required')
  if entrant_type is None:entrant_type=entrant['blueprint_id']
  elif entrant_type!=entrant['blueprint_id']:raise ValueError('Entering vehicle type changed across original frames')
  bodies=[_body(m) for m in members];other=_body(entrant)
  if not all(road.covers(b) for b in bodies+[other]):raise ValueError('Vehicle outside sourced highway')
  ordered=sorted(zip(members,bodies),key=lambda mb:mb[1].centroid.x*fx+mb[1].centroid.y*fy)
  for member,body in ordered:
   current=body.centroid.x*fx+body.centroid.y*fy
   previous=member_centers.get(member['actor_id'])
   if previous is not None:
    if current<previous-1e-4:raise ValueError('Caravan member reversed against highway direction')
    forward_motion[member['actor_id']]=forward_motion.get(member['actor_id'],False) or current>previous+1e-4
   member_centers[member['actor_id']]=current
  gaps=[]
  def extent(poly):
   values=[x*fx+y*fy for x,y in poly.exterior.coords]
   return min(values),max(values)
  entrant_min,entrant_max=extent(other)
  lateral=(-fy,fx)
  entrant_side_min,entrant_side_max=(min(x*lateral[0]+y*lateral[1] for x,y in other.exterior.coords),max(x*lateral[0]+y*lateral[1] for x,y in other.exterior.coords))
  for (rear,rb),(front,fb) in zip(ordered,ordered[1:]):
   along=(fb.centroid.x-rb.centroid.x)*fx+(fb.centroid.y-rb.centroid.y)*fy
   clearance=rb.distance(fb)
   rear_edge=extent(rb)[1];front_edge=extent(fb)[0]
   rear_side=(min(x*lateral[0]+y*lateral[1] for x,y in rb.exterior.coords),max(x*lateral[0]+y*lateral[1] for x,y in rb.exterior.coords))
   front_side=(min(x*lateral[0]+y*lateral[1] for x,y in fb.exterior.coords),max(x*lateral[0]+y*lateral[1] for x,y in fb.exterior.coords))
   in_lane=entrant_side_min>=max(rear_side[0],front_side[0])-1e-4 and entrant_side_max<=min(rear_side[1],front_side[1])+1e-4
   occupied=(front_edge>rear_edge and entrant_min>=rear_edge and entrant_max<=front_edge and in_lane and
             not rb.intersects(other) and not fb.intersects(other))
   midpoint=((fb.centroid.x+rb.centroid.x)/2,(fb.centroid.y+rb.centroid.y)/2)
   gaps.append({'rear_actor_id':rear['actor_id'],'front_actor_id':front['actor_id'],'along_center_distance_m':along,'body_clearance_m':clearance,'longitudinal_opening_m':max(0.0,front_edge-rear_edge),'gap_midpoint_distance_to_entering_body_m':other.distance(Point(midpoint)),'entering_body_in_caravan_lane':in_lane,'entering_body_wholly_between_member_bodies':occupied,'entering_body_touches_member':rb.intersects(other) or fb.intersects(other)})
  samples.append({'frame':fid,'time_s':t,'gaps':gaps,'entering_vehicle_body_area_m2':other.area})
 occupied_pairs={(g['rear_actor_id'],g['front_actor_id']) for sample in samples for g in sample['gaps'] if g['entering_body_wholly_between_member_bodies']}
 transitions=[]
 for pair in sorted(occupied_pairs):
  states=[next((g['entering_body_wholly_between_member_bodies'] for g in sample['gaps'] if (g['rear_actor_id'],g['front_actor_id'])==pair),False) for sample in samples]
  transitions.append({'rear_actor_id':pair[0],'front_actor_id':pair[1],'occupied_on_original_frame':True,'observed_entry_transition':any(not a and b for a,b in zip(states,states[1:]))})
 return {'format':'worker-caravan-spacing-observations','sources':hashes,'context_source_hashes':context_hashes,'samples':samples,'gap_occupancy':transitions,'caravan_forward_motion_observed':all(forward_motion.get(actor_id,False) for actor_id in member_ids),'member_blueprint_ids':sorted(member_types.values()),'entrant_blueprint_id':entrant_type,'sufficient_space_without_danger_judgment':'unresolved; no statutory numeric gap','legal_conclusion':'unresolved'}

